import{_ as o,a0 as l,w as r,s as d,ao as p,I as e,x as a,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？ | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？ | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？ | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210308 How to use Poetry to manage your Python projects on Fedora","title":"如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？","tag":"202103","desc":""},"relativePath":"202103/20210308 How to use Poetry to manage your Python projects on Fedora.md","filePath":"[post].md"}'),h={name:"202103/20210308 How to use Poetry to manage your Python projects on Fedora.md"};function g(c,s,u,y,k,b){const n=l("Link");return r(),d("div",null,[s[24]||(s[24]=p(`<h1 id="如何在-fedora-上使用-poetry-來管理你的-python-項目" tabindex="-1">如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？ <a class="header-anchor" href="#如何在-fedora-上使用-poetry-來管理你的-python-項目" aria-label="Permalink to “如何在 Fedora 上使用 Poetry 來管理你的 Python 項目？”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/03/Poetry_Python-816x345.jpg" alt="Python &amp; Poetry on Fedora"></p><p>Python 開發人員經常創建一個新的虛擬環境來分離項目依賴，然後用 <code>pip</code>、<code>pipenv</code> 等工具來管理它們。Poetry 是一個簡化 Python 中依賴管理和打包的工具。這篇文章將向你展示如何在 Fedora 上使用 Poetry 來管理你的 Python 項目。</p><p>與其他工具不同，Poetry 只使用一個配置文件來進行依賴管理、打包和發佈。這消除了對不同文件的需求，如 <code>Pipfile</code>、<code>MANIFEST.in</code>、<code>setup.py</code> 等。這也比使用多個工具更快。</p><p>下面詳細介紹一下開始使用 Poetry 時使用的命令。</p><h3 id="在-fedora-上安裝-poetry" tabindex="-1">在 Fedora 上安裝 Poetry <a class="header-anchor" href="#在-fedora-上安裝-poetry" aria-label="Permalink to “在 Fedora 上安裝 Poetry”">​</a></h3><p>如果你已經使用 Fedora 32 或以上版本，你可以使用這個命令直接從命令列安裝 Poetry：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install poetry</span></span></code></pre></div><p>編者注：在 Fedora Silverblue 或 CoreOs上，Python 3.9.2 是核心提交的一部分，你可以用下面的命令安裝 Poetry：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm-ostree install poetry</span></span></code></pre></div><h3 id="初始化一個項目" tabindex="-1">初始化一個項目 <a class="header-anchor" href="#初始化一個項目" aria-label="Permalink to “初始化一個項目”">​</a></h3><p>使用 <code>new</code> 命令創建一個新項目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry new poetry-project</span></span></code></pre></div><p>用 Poetry 創建的項目結構是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>├── poetry_project</span></span>
<span class="line"><span>│   └── init.py</span></span>
<span class="line"><span>├── pyproject.toml</span></span>
<span class="line"><span>├── README.rst</span></span>
<span class="line"><span>└── tests</span></span>
<span class="line"><span>    ├── init.py</span></span>
<span class="line"><span>    └── test_poetry_project.py</span></span></code></pre></div><p>Poetry 使用 <code>pyproject.toml</code> 來管理項目的依賴。最初，這個文件看起來類似於這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[tool.poetry]</span></span>
<span class="line"><span>name = &quot;poetry-project&quot;</span></span>
<span class="line"><span>version = &quot;0.1.0&quot;</span></span>
<span class="line"><span>description = &quot;&quot;</span></span>
<span class="line"><span>authors = [&quot;Kadermiyanyedi &lt;kadermiyanyedi@hotmail.com&gt;&quot;]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[tool.poetry.dependencies]</span></span>
<span class="line"><span>python = &quot;^3.9&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[tool.poetry.dev-dependencies]</span></span>
<span class="line"><span>pytest = &quot;^5.2&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[build-system]</span></span>
<span class="line"><span>requires = [&quot;poetry&gt;=0.12&quot;]</span></span>
<span class="line"><span>build-backend = &quot;poetry.masonry.api&quot;</span></span></code></pre></div><p>這個文件包含 4 個部分：</p>`,18)),e("ul",null,[s[3]||(s[3]=e("li",null,"第一部分包含描述項目的信息，如項目名稱、項目版本等。",-1)),s[4]||(s[4]=e("li",null,"第二部分包含項目的依賴。這些依賴是構建項目所必需的。",-1)),s[5]||(s[5]=e("li",null,"第三部分包含開發依賴。",-1)),e("li",null,[s[1]||(s[1]=a("第四部分描述的是符合 ",-1)),t(n,{href:"https://www.python.org/dev/peps/pep-0517/"},{default:i(()=>[...s[0]||(s[0]=[a("PEP 517",-1)])]),_:1}),s[2]||(s[2]=a(" 的構建系統。",-1))])]),s[25]||(s[25]=p(`<p>如果你已經有一個項目，或者創建了自己的項目文件夾，並且你想使用 Poetry，請在你的項目中運行 <code>init</code> 命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry init</span></span></code></pre></div><p>在這個命令之後，你會看到一個交互式的 shell 來配置你的項目。</p><h3 id="創建一個虛擬環境" tabindex="-1">創建一個虛擬環境 <a class="header-anchor" href="#創建一個虛擬環境" aria-label="Permalink to “創建一個虛擬環境”">​</a></h3><p>如果你想創建一個虛擬環境或激活一個現有的虛擬環境，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry shell</span></span></code></pre></div><p>Poetry 默認在 <code>/home/username/.cache/pypoetry</code> 項目中創建虛擬環境。你可以通過編輯 Poetry 配置來更改默認路徑。使用下面的命令查看配置列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry config --list</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cache-dir = &quot;/home/username/.cache/pypoetry&quot;</span></span>
<span class="line"><span>virtualenvs.create = true</span></span>
<span class="line"><span>virtualenvs.in-project = true</span></span>
<span class="line"><span>virtualenvs.path = &quot;{cache-dir}/virtualenvs&quot;</span></span></code></pre></div><p>修改 <code>virtualenvs.in-project</code> 配置變量，在項目目錄下創建一個虛擬環境。Poetry 命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry config virtualenv.in-project true</span></span></code></pre></div><h3 id="添加依賴" tabindex="-1">添加依賴 <a class="header-anchor" href="#添加依賴" aria-label="Permalink to “添加依賴”">​</a></h3><p>使用 <code>poetry add</code> 命令為項目安裝一個依賴：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry add django</span></span></code></pre></div><p>你可以使用帶有 <code>--dev</code> 選項的 <code>add</code> 命令來識別任何只用於開發環境的依賴：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry add black --dev</span></span></code></pre></div><p><code>add</code> 命令會創建一個 <code>poetry.lock</code> 文件，用來跟蹤軟件包的版本。如果 <code>poetry.lock</code> 文件不存在，那麼會安裝 <code>pyproject.toml</code> 中所有依賴項的最新版本。如果 <code>poetry.lock</code> 存在，Poetry 會使用文件中列出的確切版本，以確保每個使用這個項目的人的軟件包版本是一致的。</p><p>使用 <code>poetry install</code> 命令來安裝當前項目中的所有依賴：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry install</span></span></code></pre></div><p>通過使用 <code>--no-dev</code> 選項防止安裝開發依賴：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry install --no-dev</span></span></code></pre></div><h3 id="列出軟件包" tabindex="-1">列出軟件包 <a class="header-anchor" href="#列出軟件包" aria-label="Permalink to “列出軟件包”">​</a></h3><p><code>show</code> 命令會列出所有可用的軟件包。<code>--tree</code> 選項將以樹狀列出軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry show --tree</span></span>
<span class="line"><span></span></span>
<span class="line"><span>django 3.1.7 A high-level Python Web framework that encourages rapid development and clean, pragmatic design.</span></span>
<span class="line"><span>├── asgiref &gt;=3.2.10,&lt;4</span></span>
<span class="line"><span>├── pytz *</span></span>
<span class="line"><span>└── sqlparse &gt;=0.2.2</span></span></code></pre></div><p>包含軟件包名稱，以列出特定軟件包的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry show requests</span></span>
<span class="line"><span></span></span>
<span class="line"><span>name         : requests</span></span>
<span class="line"><span>version      : 2.25.1</span></span>
<span class="line"><span>description  : Python HTTP for Humans.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>dependencies</span></span>
<span class="line"><span> - certifi &gt;=2017.4.17</span></span>
<span class="line"><span> - chardet &gt;=3.0.2,&lt;5</span></span>
<span class="line"><span> - idna &gt;=2.5,&lt;3</span></span>
<span class="line"><span> - urllib3 &gt;=1.21.1,&lt;1.27</span></span></code></pre></div><p>最後，如果你想知道軟件包的最新版本，你可以通過 <code>--latest</code> 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ poetry show --latest</span></span>
<span class="line"><span></span></span>
<span class="line"><span>idna     2.10      3.1    Internationalized Domain Names in Applications</span></span>
<span class="line"><span>asgiref  3.3.1     3.3.1  ASGI specs, helper code, and adapters</span></span></code></pre></div><h3 id="更多信息" tabindex="-1">更多信息 <a class="header-anchor" href="#更多信息" aria-label="Permalink to “更多信息”">​</a></h3>`,28)),e("p",null,[s[7]||(s[7]=a("Poetry 的更多詳情可在",-1)),t(n,{href:"https://python-poetry.org/docs/"},{default:i(()=>[...s[6]||(s[6]=[a("文檔",-1)])]),_:1}),s[8]||(s[8]=a("中獲取。",-1))]),s[26]||(s[26]=e("hr",null,null,-1)),e("p",null,[s[10]||(s[10]=a("via: ",-1)),t(n,{href:"https://fedoramagazine.org/how-to-use-poetry-to-manage-your-python-projects-on-fedora/"},{default:i(()=>[...s[9]||(s[9]=[a("https://fedoramagazine.org/how-to-use-poetry-to-manage-your-python-projects-on-fedora/",-1)])]),_:1})]),e("p",null,[s[15]||(s[15]=a("作者：",-1)),t(n,{href:"https://fedoramagazine.org/author/moonkat/"},{default:i(()=>[...s[11]||(s[11]=[a("Kader Miyanyedi",-1)])]),_:1}),s[16]||(s[16]=a(" 選題：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[17]||(s[17]=a(" 譯者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[13]||(s[13]=[a("geekpi",-1)])]),_:1}),s[18]||(s[18]=a(" 校對：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[14]||(s[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[21]||(s[21]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[19]||(s[19]=[a("LCTT",-1)])]),_:1}),s[22]||(s[22]=a(" 原創編譯，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[20]||(s[20]=[a("Linux中國",-1)])]),_:1}),s[23]||(s[23]=a(" 榮譽推出",-1))])])}const v=o(h,[["render",g]]);export{P as __pageData,v as default};
